# ---------- traces by simulation ----------
def stack_trace(ops, mx):
    st, rows = [], []
    for op in ops:
        if op == "POP":
            if st:
                v = st.pop(); res = f"popped {v}"
            else:
                res = "UNDERFLOW"
        else:
            v = op.split()[1]
            if len(st) == mx:
                res = "OVERFLOW"
            else:
                st.append(v); res = "pushed"
        rows.append((op, " ".join(st) or "empty", len(st) - 1, res))
    return table(["Operation", "Stack (bottom→top)", "TOP", "Result"], rows)


def queue_trace(ops, mx, circular):
    q = [""] * mx
    f = r = -1
    rows = []
    for op in ops:
        if op == "DEL":
            if f == -1 or (not circular and f > r):
                res = "UNDERFLOW"
            else:
                res = f"deleted {q[f]}"
                q[f] = ""
                if circular:
                    if f == r: f = r = -1
                    else: f = (f + 1) % mx
                else:
                    f += 1
        else:
            v = op.split()[1]
            full = ((r + 1) % mx == f) if circular else (r == mx - 1)
            if full:
                res = "OVERFLOW (full)"
            else:
                if f == -1: f = 0
                r = (r + 1) % mx if circular else r + 1
                q[r] = v
                res = f"at [{r}]"
        rows.append((op, " | ".join(x or "_" for x in q), f, r, res))
    return table(["Operation", "Q[0..%d]" % (mx - 1), "F", "R", "Result"], rows)


def pf(expr, nid, extra=""):
    p, t = postfix_table(expr)
    return N(nid, f"Convert the infix expression {expr} into postfix form using a stack. Show the stack at each step.",
             t + f"<p><b>Postfix: {' '.join(p)}</b></p>" + extra)


def pre(expr, nid):
    p, rev, t = prefix_table(expr)
    return N(nid, f"Convert the infix expression {expr} into prefix form.",
             f"<p>Step 1, reverse the infix (swap brackets): <b>{' '.join(rev)}</b></p><p>Step 2, convert (equal precedence is pushed):</p>"
             + t + f"<p>Step 3, reverse the output: <b>Prefix = {' '.join(p)}</b></p>")


v8, t8 = eval_postfix_table("6 2 3 + - 3 8 2 / + * 2 ^ 3 +".split())
v7, t7 = eval_postfix_table("5 3 + 8 2 - *".split())
v9, t9 = eval_prefix_table("- * + 4 3 2 5".split())
assert (v7, v8, v9) == (48, 52, 9)

